Counter :: struct {
    value: i32
}

increment :: fn(counter: ref Counter) {
    counter.value += 1
}

main :: fn() {
    counter := Counter{value: 0}
    counter.value = 41
    increment(counter)
    io.println("{}", counter.value)
}
